const HttpStatus = { ok: 200, notFound: 404, serverError: 500 };

type StatusCode = (typeof HttpStatus)[keyof typeof HttpStatus];
// BUG: StatusCode is `number`, not 200 | 404 | 500

function describe(code: StatusCode) {
  // We wanted only the three codes; any number is accepted now
  return code;
}

console.log(describe(200));
console.log(describe(999)); // should have been rejected, but isn't

solution.code:
const HttpStatus = { ok: 200, notFound: 404, serverError: 500 } as const;

type StatusCode = (typeof HttpStatus)[keyof typeof HttpStatus];
// StatusCode is now 200 | 404 | 500

function describe(code: StatusCode) {
  return code;
}

console.log(describe(200));
// describe(999); // now a COMPILE error — caught!

function pick<T, K extends keyof T>(obj: T, keys: K[]): Pick<T, K> {
  const result = {} as Pick<T, K>;
  for (const key of keys) {
    result[key] = obj[key];
  }
  return result;
}

const user = { id: 1, name: 'Ada', email: 'a@x.io', active: true };
const small = pick(user, ['id', 'name']);
console.log(JSON.stringify(small));
console.log(small.name); // typed string
